import java.io.*;

public class Main {
    static byte[] in;
    static int pos;

    static void skipSpace() {
        while (pos < in.length && (in[pos] == ' ' || in[pos] == '\n' || in[pos] == '\r' || in[pos] == '\t')) pos++;
    }

    // Parses one JSON string of ASCII characters at pos.
    static String parseString() {
        StringBuilder out = new StringBuilder();
        pos++; // opening quote
        while (in[pos] != '"') {
            if (in[pos] == '\\') {
                char e = (char) in[pos + 1];
                pos += 2;
                if (e == 'u') {
                    out.append((char) Integer.parseInt(new String(in, pos, 4), 16));
                    pos += 4;
                } else {
                    out.append("\"\\/\b\f\n\r\t".charAt("\"\\/bfnrt".indexOf(e)));
                }
            } else {
                out.append((char) in[pos++]);
            }
        }
        pos++; // closing quote
        return out.toString();
    }

    public static void main(String[] args) throws IOException {
        in = System.in.readAllBytes();
        skipSpace();
        pos++; // [
        skipSpace();
        String s = parseString();
        skipSpace();
        pos++; // ,
        skipSpace();
        String t = parseString();
        skipSpace();
        pos++; // ,
        skipSpace();
        int end = pos;
        while (end < in.length && (in[end] == '-' || (in[end] >= '0' && in[end] <= '9'))) end++;
        long k = Long.parseLong(new String(in, pos, end - pos));
        long cost = 0;
        int left = 0, answer = 0;
        for (int right = 0; right < s.length(); right++) {
            cost += Math.abs(s.charAt(right) - t.charAt(right));
            while (cost > k) {
                cost -= Math.abs(s.charAt(left) - t.charAt(left));
                left++;
            }
            answer = Math.max(answer, right - left + 1);
        }
        System.out.println(answer);
    }
}

