	json.Unmarshal(v[1], &t)
	json.Unmarshal(v[2], &k)
	abs := func(x int) int64 {
		if x < 0 {
			return int64(-x)
		}
		return int64(x)
	}
	var cost int64
	left, answer := 0, 0
	for right := 0; right < len(s); right++ {
		cost += abs(int(s[right]) - int(t[right]))
